    private static readonly FrozenDictionary<string, AttributeDefinition> ByKey =
        Definitions.ToFrozenDictionary(static definition => definition.Key, StringComparer.Ordinal);
    private static readonly AttributeDefinition[] Templates =
        System.Linq.Enumerable.ToArray(System.Linq.Enumerable.Where(Definitions, static definition => definition.Type.StartsWith("template[", StringComparison.Ordinal)));
    public static IReadOnlyList<AttributeDefinition> All { get; } = Array.AsReadOnly(Definitions);
    public static AttributeDefinition? Find(string key)
    {
        if (ByKey.TryGetValue(key, out var definition)) return definition;
        foreach (var template in Templates)
            if (key.Length > template.Key.Length + 1 && key.StartsWith(template.Key, StringComparison.Ordinal) && key[template.Key.Length] == '.') return template;
        return null;
    }
}

